def start_profile(
    self,
    # The output directory
    output_dir: str | None = None,
    # If set, it profile as many as this number of steps.
    # If it is set, profiling is automatically stopped after this step, and
    # the caller doesn't need to run stop_profile.
    start_step: int | None = None,
    num_steps: int | None = None,
    activities: list[str] | None = None,
    profile_by_stage: bool = False,
    with_stack: bool | None = None,
    record_shapes: bool | None = None,
):
    response = requests.post(
        f"http://{self.server_host}:{self.server_port}/start_profile",
        json={
            "output_dir": output_dir,
            "start_step": start_step,
            "num_steps": num_steps,
            "activities": activities,
            "profile_by_stage": profile_by_stage,
            "with_stack": with_stack,
            "record_shapes": record_shapes,
        },
    )
    response.raise_for_status()
    return response

def stop_profile(self):
    response = requests.post(f"http://{self.server_host}:{self.server_port}/stop_profile", json={})
    response.raise_for_status()
    return response

def simulate_crash(self):
    if self.args.rollout_external or not getattr(self, "process", None):
        logger.info(
            "simulate_crash called but no local engine process exists (rollout_external=%s); skip kill",
            self.args.rollout_external,
        )
        return

    logger.info(f"Simulating crash on engine {self.server_host}:{self.server_port}...")

    with inplace_modify_args(args, heal_load_overrides):
        (self.model, self.optimizer, self.opt_param_scheduler, loaded_rollout_id) = initialize_model_and_optimizer(
            args, role, checkpointing_context=checkpointing_context
        )

    parallel_state = get_parallel_state()
    if parallel_state.cp.size > 1:
        from miles_plugins.models.cp_utils import detect_and_setup_hybrid_cp

        for model_chunk in self.model:
            detect_and_setup_hybrid_cp(
                model_chunk, parallel_state.cp.group, parallel_state.cp.rank, parallel_state.cp.size
            )

    verify_megatron_parallel_state(self.model)

    start_rollout_id = loaded_rollout_id + 1
    self._asleep = False

    if role == "critic":
        if self.args.offload_train:
            self.sleep()
        return start_rollout_id

    self.weights_backuper = TensorBackuper.create(
        source_getter=lambda: named_params_and_buffers(
            self.args,
            self.model,
            convert_to_global_name=args.megatron_to_hf_mode == "raw",
            translate_gpu_to_cpu=not self.args.enable_weights_backuper,
        ),
        single_tag=None if args.enable_weights_backuper else "actor",
    )
    self._active_model_tag: str | None = "actor"
    if self._enable_weight_backup:
        self.weights_backuper.backup("actor")

    if with_ref:
        self.load_other_checkpoint("ref", args.ref_load)

    # Load teacher model for Megatron-based on-policy distillation
    if with_opd_teacher:
        self.load_other_checkpoint("teacher", args.opd_teacher_load)

    if self.args.keep_old_actor:
        # Load old_actor checkpoint
        self.load_other_checkpoint("old_actor", args.load)
        # Create rollout_actor as a copy of current actor
        if args.update_weights_interval == 1:
            self.weights_backuper.backup("rollout_actor")

    if self.args.vocab_size is None:
        self.args.vocab_size = self.tokenizer.vocab_size

    if self.args.colocate:
        update_weight_cls = UpdateWeightFromTensor
    else:
        if self.args.update_weight_transfer_mode == "broadcast":
            update_weight_cls = UpdateWeightFromDistributed
        elif self.args.update_weight_transfer_mode == "disk-delta":
            # Lazy import: keeps the delta deps (numpy/zstandard/xxhash) off the other paths.
            from .update_weight.update_weight_from_distributed.delta import UpdateWeightFromDiskDelta

            update_weight_cls = UpdateWeightFromDiskDelta
        else:
            update_weight_cls = UpdateWeightP2P
    self.weight_updater = update_weight_cls(
        self.args,
        self.model,
        weights_getter=lambda: self.weights_backuper.get("actor"),
        model_name=type(self.hf_config).__name__.lower() if self.args.model_name is None else self.args.model_name,
        quantization_config=getattr(self.hf_config, "quantization_config", None),
        is_lora=is_lora_enabled(args),
    )

    # Adapters currently loaded into Megatron slots on this rank.
    self.loaded_adapters: dict[str, object] = {}
    # Adapters with stale engine-side weights (newly loaded or just trained);
    # consumed by the next update_weights. Identical on every rank.
    self._multi_lora_pending_push: set[str] = set()

    # empty cache after initialization
    clear_memory()

    self._switch_model("actor")
    if self.args.offload_train:
        self.sleep()

    self.rollout_data_postprocess = None
    if (x := self.args.rollout_data_postprocess_path) is not None:
        from miles.utils.misc import load_function

        self.rollout_data_postprocess = load_function(x)

    self.prof.on_init_end()

    return start_rollout_id

@with_logs
@timer
def sleep(self) -> None:
    assert self.args.offload_train
    if self._asleep:
        logger.info("sleep() called while already offloaded; skipping")
        return

    clear_memory(clear_host_memory=True)
    print_memory("before offload model")
    should_log_cpu_memory = is_first_replica_megatron_main_rank() and hasattr(self, "_last_rollout_id")

    destroy_process_groups()

    tag = "default" if is_lora_enabled(self.args) else None
    torch_memory_saver.pause(tag=tag)

    self._asleep = True
    print_memory("after offload model")

    if should_log_cpu_memory:
        log_cpu_memory(self._last_rollout_id, self.args, "after_offload_train")

async def generate_and_rm_group(
    state: GenerateState, group: list[Sample], sampling_params: dict[str, Any], evaluation: bool = False
) -> list[Sample]:
    args = state.args

    if state.aborted:
        return group

    if policy_uses_routing_key(args):
        for sample in group:
            if sample.routing_key is None:
                sample.routing_key = str(uuid.uuid4())

    log_prefix = f"[group indices={[getattr(s, 'index', '?') for s in group]}]"
    logger.debug(f"{log_prefix} Starting group with {len(group)} samples")
    tasks = []
    for idx, sample in enumerate(group):
        current_sampling_params = sampling_params.copy()
        if getattr(args, "sglang_enable_deterministic_inference", False):
            current_sampling_params["sampling_seed"] = args.rollout_seed + idx
        tasks.append(
            asyncio.create_task(generate_and_rm(state, sample, current_sampling_params, evaluation=evaluation))
        )

    group = await asyncio.gather(*tasks)
    logger.debug(f"{log_prefix} [group] All {len(group)} samples completed")
    if state.aborted:
        return group

    if args.group_rm:
        await batched_async_rm(args, group, inplace_set_reward_field=True)

    return group


def compute_sampling_params(
    args,
    *,
    # after unifying configuration, this can be further refactored
    temperature,
    top_p,
    top_k,
    max_new_tokens,
):
    return dict(
        temperature=temperature,
        top_p=top_p,
        top_k=top_k,
        max_new_tokens=max_new_tokens,
        stop=args.rollout_stop,
        stop_token_ids=args.rollout_stop_token_ids,
        skip_special_tokens=args.rollout_skip_special_tokens,
        no_stop_trim=True,
        spaces_between_special_tokens=False,
    )


class InferenceRolloutFn:
    def __init__(self, input: RolloutFnConstructorInput):
        self.data_source = input.data_source
        self.state = GenerateState(input.args)
        self.eval_prompt_dataset_cache = {}

    async def __call__(self, input: RolloutFnInput) -> RolloutFnOutput:
        if input.evaluation:
            return await self._call_eval(input)
        return await self._call_train(input)

    async def _call_train(self, input: RolloutFnTrainInput) -> RolloutFnTrainOutput:
        from miles.rollout.inference_rollout.inference_rollout_train import generate_rollout_async

        output, aborted_samples = await generate_rollout_async(
            self.state, input.rollout_id, self.data_source.get_samples
        )
        self.data_source.add_samples(aborted_samples)
        return output

    async def _call_eval(self, input: RolloutFnEvalInput) -> RolloutFnEvalOutput:
        from miles.rollout.inference_rollout.inference_rollout_eval import eval_rollout_single_dataset

        assert not self.state.args.group_rm, "Group RM is not supported for eval rollout"

        coros = []
        for dataset_cfg in getattr(self.state.args, "eval_datasets", []) or []:
            coros.append(eval_rollout_single_dataset(self.state, dataset_cfg, self.eval_prompt_dataset_cache))
        results_list = await asyncio.gather(*coros)
        results = {k: v for r in results_list for k, v in r.items()}
        return RolloutFnEvalOutput(data=results)

"""
Utils to integrate SGLang's `/generate` endpoint with RL things like Sample.
"""

from copy import deepcopy
from typing import Any

import numpy as np
import pybase64

from miles.utils.lora import LORA_ADAPTER_NAME, is_lora_enabled
from miles.utils.processing_utils import encode_image_for_rollout_engine, extract_multimodal_train_inputs
from miles.utils.types import Sample


# Make this an isolated function because users may want to compute their own
def compute_prompt_ids_from_sample(state, sample, tools=None):
    prompt = sample.prompt

    if state.processor and sample.multimodal_inputs and any(v is not None for v in sample.multimodal_inputs.values()):
        processor_output = state.processor(text=prompt, **sample.multimodal_inputs)
        prompt_ids = processor_output["input_ids"][0]

        # TODO shall we move it to other places? then can make this function immutable
        sample.multimodal_train_inputs = extract_multimodal_train_inputs(processor_output)

        return prompt_ids
    else:
        if not isinstance(prompt, str):
            prompt = state.tokenizer.apply_chat_template(
                prompt, tokenize=False, add_generation_prompt=True, tools=tools
            )

        return state.tokenizer.encode(prompt, add_special_tokens=False)


def policy_uses_routing_key(args) -> bool:
    return args.sglang_router_policy in ("consistent_hashing", "manual")


def compute_routing_headers(args, sample: Sample) -> dict[str, str] | None:
    if policy_uses_routing_key(args) and not sample.routing_key:
        raise ValueError(
            f"router policy {args.sglang_router_policy} routes by X-SMG-Routing-Key, "
            f"but sample (index={sample.index}) has no routing_key set"
        )
    if sample.routing_key:
        return {"X-SMG-Routing-Key": sample.routing_key}
    return None


def compute_request_payload(
    args,
    input_ids: list[int],
    sampling_params: dict,
    multimodal_inputs: dict | None = None,
) -> tuple[dict[str, Any] | None, Sample.Status | None]:
    sampling_params = deepcopy(sampling_params)
    max_new_tokens = sampling_params.pop("max_new_tokens", args.rollout_max_response_len)
    if x := args.rollout_max_context_len:
        max_new_tokens = min(max_new_tokens, x - len(input_ids))
    if max_new_tokens <= 0:
        return None, Sample.Status.TRUNCATED

    payload = {
        "input_ids": input_ids,
        "sampling_params": {**sampling_params, "max_new_tokens": max_new_tokens},
        "return_logprob": True,
        "return_routed_experts": args.use_rollout_routing_replay,
        "return_indexer_topk": args.use_rollout_indexer_replay,
    }
    if is_lora_enabled(args):
        payload["lora_path"] = LORA_ADAPTER_NAME
    if image_data := (multimodal_inputs or {}).get("images"):
        payload["image_data"] = [encode_image_for_rollout_engine(image) for image in image_data]

    return payload, None


async def update_sample_from_response(
    args, sample: Sample, payload: dict, output: dict, update_loss_mask: bool = False
):
    # Initialize sample.tokens for the first turn
    if (len(sample.response) == 0) and not sample.tokens:
        sample.tokens = payload["input_ids"]

    if x := output["meta_info"].get("output_token_logprobs"):
        new_response_tokens = [item[1] for item in x]
        new_response_log_probs = [item[0] for item in x]
    else:
        new_response_tokens, new_response_log_probs = [], []

    # Update sample with tokens directly - avoiding re-tokenization
    sample.tokens = sample.tokens + new_response_tokens
    sample.response_length += len(new_response_tokens)
    sample.response += output["text"]

    if sample.rollout_log_probs is None:
        sample.rollout_log_probs = []
    sample.rollout_log_probs += new_response_log_probs

    if update_loss_mask:
        if sample.loss_mask is None:
            sample.loss_mask = []
        sample.loss_mask += [1] * len(new_response_tokens)

    # TODO handle multi-turn cases (may need concat instead of assignment)
    sample.rollout_routed_experts = get_routed_experts_from_response(args, output, sample)
    sample.rollout_indexer_topk = get_indexer_topk_from_response(args, output, sample)

    # TODO may unify (currently there are both methods inside Sample and separate functions)
    sample.update_from_meta_info(args, output["meta_info"])


def _decode_topk_buffer(info: str, num_tokens: int, num_layers: int, topk: int) -> np.ndarray:
    x = np.frombuffer(pybase64.b64decode(info.encode("ascii")), dtype=np.int32)
    if num_tokens <= 0:
        return np.empty((0, num_layers, max(0, topk)), dtype=np.int32)
    if topk == -1:  # indexer: topk dim recovered from buffer length
        topk = len(x) // (num_tokens * num_layers)
    return x.reshape(num_tokens, num_layers, topk)


def get_routed_experts_from_response(args, output, sample):
    info = output["meta_info"].get("routed_experts")
    if info is None:
        return None
    return _decode_topk_buffer(info, len(sample.tokens) - 1, args.num_layers, args.moe_router_topk)


def get_indexer_topk_from_response(args, output, sample):
    info = output["meta_info"].get("indexer_topk")
    if info is None:
        return None
    num_layers = output["meta_info"].get("indexer_topk_num_layers")
    assert num_layers is not None, (
        "Server returned indexer_topk without indexer_topk_num_layers; "
        "sglang-miles must include the layer count in meta_info."
    )
    return _decode_topk_buffer(info, len(sample.tokens) - 1, num_layers, -1)

