import pickle, zipfile, io

class DummyUnpickler(pickle.Unpickler):
    def find_class(self, module, name):
        try:
            return super().find_class(module, name)
        except Exception:
            return lambda *args: args

for fname in ["outputs/rollout_data/0.pt", "outputs/rollout_data/45.pt", "outputs/rollout_data/91.pt"]:
    with zipfile.ZipFile(fname, "r") as zf:
        for name in zf.namelist():
            if name.endswith("data.pkl"):
                data = DummyUnpickler(io.BytesIO(zf.read(name))).load()
                samples = data["samples"]
                accs = [1.0 if s["reward"].get("acc") else 0.0 for s in samples]
                scores = [s["reward"].get("score") for s in samples]
                lens = [s.get("response_length", 0) for s in samples]
                wvs = [tuple(s.get("weight_versions", [])) for s in samples]
                from collections import Counter
                print(f"{fname}: n={len(samples)}, solve_rate={sum(accs)/len(accs):.4f}, mean_score={sum(scores)/len(scores):.4f}, mean_len={sum(lens)/len(lens):.1f}, weight_versions={Counter(wvs)}")
'

